package sso;import org.springframework.boot.SpringApplication;import org.springframework.boot.autoconfigure.SpringBootApplication;import org.springframework.boot.autoconfigure.jdbc.DataSourceAutoConfiguration;import org.springframework.boot.autoconfigure.orm.jpa.HibernateJpaAutoConfiguration;import org.springframework.boot.context.properties.ConfigurationPropertiesScan;@SpringBootApplication(exclude = {	    DataSourceAutoConfiguration.class,	    HibernateJpaAutoConfiguration.class	})@ConfigurationPropertiesScanpublic class SsoApplication {    public static void main(String[] args) {        SpringApplication.run(SsoApplication.class, args);    }}